def prop_key(p):
    if isinstance(p, JSBigInt): return str(p.value)
    if isinstance(p, (int,float)) and not isinstance(p,bool):
        if isinstance(p,float) and p.is_integer(): return str(int(p))
    return to_string(p)

def get_prop(obj, prop):
    k=prop_key(prop)
    if obj is UNDEFINED or obj is None:
        raise JSThrown(JSErrorObject("TypeError", "cannot read property"))
    if isinstance(obj, JSArray):
        if k == 'length': return len(obj.items)
        if re.match(r'^\d+$', k):
            idx=int(k); return obj.items[idx] if 0 <= idx < len(obj.items) else UNDEFINED
        if k in obj.props: return obj.props[k]
        fn=array_method(k)
        if fn: return fn
        return UNDEFINED
    if isinstance(obj, str):
        if k == 'length': return len(obj)
        if re.match(r'^\d+$', k):
            idx=int(k); return obj[idx] if 0 <= idx < len(obj) else UNDEFINED
        fn=string_method(k)
        if fn: return fn
        return UNDEFINED
    if isinstance(obj, (int,float,JSBigInt,bool)):
        fn=number_method(k)
        if fn: return fn
        return UNDEFINED
    if isinstance(obj, JSRegExp):
        fn=regexp_method(k)
        if fn: return fn
        if k in ('source','flags'): return obj.pattern if k=='source' else obj.flags
        return UNDEFINED
    if isinstance(obj, JSObject):
        if k in obj.props: return obj.props[k]
        return UNDEFINED
    return UNDEFINED

def set_prop(obj, prop, value):
    k=prop_key(prop)
    if isinstance(obj, JSArray):
        if k == 'length':
            n=max(0,to_int(value)); obj.items=obj.items[:n]; return value
        if re.match(r'^\d+$', k):
            idx=int(k)
            while len(obj.items)<=idx: obj.items.append(UNDEFINED)
            obj.items[idx]=value; return value
        obj.props[k]=value; return value
    if isinstance(obj, JSObject): obj.props[k]=value; return value
    raise JSThrown(JSErrorObject("TypeError", "not an object"))

def assign_target(target, value, env, declare=False):
    if isinstance(target, Var):
        if declare and not env.has_local(target.name): env.declare(target.name, value)
        else: env.set(target.name, value)
        return value
    if isinstance(target, Member):
        o,p=target.ref(env); return set_prop(o,p,value)
    raise JSThrown(JSErrorObject("ReferenceError", "invalid assignment target"))

def native(name, func): return JSFunction(name=name, native=func)

def array_method(name):
    def wrap(fn): return native(name, fn)
    if name == 'push': return wrap(lambda args,this,env: (this.items.extend(args) or len(this.items)))
    if name == 'pop': return wrap(lambda args,this,env: this.items.pop() if this.items else UNDEFINED)
    if name == 'shift': return wrap(lambda args,this,env: this.items.pop(0) if this.items else UNDEFINED)
    if name == 'unshift': return wrap(lambda args,this,env: (this.items.__setitem__(slice(0,0), args) or len(this.items)))
    if name in ('join','toString'):
        return wrap(lambda args,this,env: (to_string(args[0]) if args and args[0] is not UNDEFINED else ',').join('' if x is UNDEFINED or x is None else to_string(x) for x in this.items))
    if name == 'map':
        def f(args,this,env):
            cb=args[0] if args else UNDEFINED
            return JSArray([cb.call([x,i,this], args[1] if len(args)>1 else UNDEFINED, env) if isinstance(cb,JSFunction) else UNDEFINED for i,x in enumerate(this.items)])
        return wrap(f)
    if name == 'filter':
        def f(args,this,env):
            cb=args[0] if args else UNDEFINED; out=[]
            for i,x in enumerate(this.items):
                if isinstance(cb,JSFunction) and is_truthy(cb.call([x,i,this], UNDEFINED, env)): out.append(x)
            return JSArray(out)
        return wrap(f)
    if name == 'forEach':
        def f(args,this,env):
            cb=args[0] if args else UNDEFINED
            if isinstance(cb,JSFunction):
                for i,x in enumerate(this.items): cb.call([x,i,this], UNDEFINED, env)
            return UNDEFINED
        return wrap(f)
    if name == 'reduce':
        def f(args,this,env):
            cb=args[0] if args else UNDEFINED
            if not isinstance(cb,JSFunction): raise JSThrown(JSErrorObject('TypeError','not a function'))
            it=list(this.items)
            if len(args)>1: acc=args[1]
            elif it: acc=it.pop(0)
            else: raise JSThrown(JSErrorObject('TypeError','empty array'))
            start = 0 if len(args)>1 else 1
            for i,x in enumerate(this.items[start:], start): acc=cb.call([acc,x,i,this], UNDEFINED, env)
            return acc
        return wrap(f)
    if name == 'slice':
        return wrap(lambda args,this,env: JSArray(this.items[(to_int(args[0]) if args else 0):(to_int(args[1]) if len(args)>1 and args[1] is not UNDEFINED else len(this.items))]))
    if name == 'splice':
        def f(args,this,env):
            start=to_int(args[0]) if args else 0
            if start<0: start=max(0,len(this.items)+start)
            delete=to_int(args[1]) if len(args)>1 else len(this.items)-start
            removed=this.items[start:start+delete]
            this.items[start:start+delete]=args[2:]
            return JSArray(removed)
        return wrap(f)
    if name == 'indexOf': return wrap(lambda args,this,env: next((i for i,x in enumerate(this.items) if loose_equal(x,args[0] if args else UNDEFINED)), -1))
    if name == 'includes': return wrap(lambda args,this,env: any(loose_equal(x,args[0] if args else UNDEFINED) for x in this.items))
    if name == 'reverse': return wrap(lambda args,this,env: (this.items.reverse() or this))
    if name == 'sort':
        def f(args,this,env):
            cb=args[0] if args else UNDEFINED
            if isinstance(cb,JSFunction):
                import functools
                def cmp(a,b): return to_int(cb.call([a,b], UNDEFINED, env))
                this.items.sort(key=functools.cmp_to_key(cmp))
            else: this.items.sort(key=lambda x: to_string(x))
            return this
        return wrap(f)
    if name == 'concat':
        def f(args,this,env):
            out=list(this.items)
            for a in args: out.extend(a.items if isinstance(a,JSArray) else [a])
            return JSArray(out)
        return wrap(f)
    if name == 'every':
        return wrap(lambda args,this,env: all(isinstance(args[0],JSFunction) and is_truthy(args[0].call([x,i,this],UNDEFINED,env)) for i,x in enumerate(this.items)))
    if name == 'some':
        return wrap(lambda args,this,env: any(isinstance(args[0],JSFunction) and is_truthy(args[0].call([x,i,this],UNDEFINED,env)) for i,x in enumerate(this.items)))
    if name == 'find':
        def f(args,this,env):
            cb=args[0] if args else UNDEFINED
            for i,x in enumerate(this.items):
                if isinstance(cb,JSFunction) and is_truthy(cb.call([x,i,this],UNDEFINED,env)): return x
            return UNDEFINED
        return wrap(f)
    if name == 'findIndex':
        def f(args,this,env):
            cb=args[0] if args else UNDEFINED
            for i,x in enumerate(this.items):
                if isinstance(cb,JSFunction) and is_truthy(cb.call([x,i,this],UNDEFINED,env)): return i
            return -1
        return wrap(f)
    if name == 'at': return wrap(lambda args,this,env: this.items[(to_int(args[0]) if args else 0) % len(this.items)] if this.items else UNDEFINED)
    return None

def string_method(name):
    def wrap(fn): return native(name, fn)
    if name == 'toUpperCase': return wrap(lambda args,this,env: str(this).upper())
    if name == 'toLowerCase': return wrap(lambda args,this,env: str(this).lower())
    if name == 'trim': return wrap(lambda args,this,env: str(this).strip())
    if name == 'trimStart': return wrap(lambda args,this,env: str(this).lstrip())
    if name == 'trimEnd': return wrap(lambda args,this,env: str(this).rstrip())
    if name == 'charAt': return wrap(lambda args,this,env: str(this)[to_int(args[0]) if args else 0:to_int(args[0]) + 1 if args else 1])
    if name == 'charCodeAt':
        def f(args,this,env):
            i=to_int(args[0]) if args else 0; s=str(this)
            return ord(s[i]) if 0 <= i < len(s) else float('nan')
        return wrap(f)
    if name in ('substring','substr','slice'):
        def f(args,this,env):
            s=str(this); start=to_int(args[0]) if args else 0; end=to_int(args[1]) if len(args)>1 and args[1] is not UNDEFINED else len(s)
            if name=='substring':
                start=max(0,start); end=max(0,end)
                if start>end: start,end=end,start
            else:
                if start<0: start=len(s)+start
                if name=='substr': end=start+end if len(args)>1 else len(s)
            return s[start:end]
        return wrap(f)
    if name == 'split':
        def f(args,this,env):
            s=str(this)
            if not args or args[0] is UNDEFINED: return JSArray([s])
            sep=to_string(args[0]); lim=to_int(args[1]) if len(args)>1 else None
            arr=list(s) if sep=='' else s.split(sep)
            if lim is not None: arr=arr[:lim]
            return JSArray(arr)
        return wrap(f)
    if name == 'indexOf': return wrap(lambda args,this,env: str(this).find(to_string(args[0]) if args else 'undefined'))
    if name == 'lastIndexOf': return wrap(lambda args,this,env: str(this).rfind(to_string(args[0]) if args else 'undefined'))
    if name == 'includes': return wrap(lambda args,this,env: (to_string(args[0]) if args else 'undefined') in str(this))
    if name == 'startsWith': return wrap(lambda args,this,env: str(this).startswith(to_string(args[0]) if args else 'undefined'))
    if name == 'endsWith': return wrap(lambda args,this,env: str(this).endswith(to_string(args[0]) if args else 'undefined'))
    if name == 'replace':
        def f(args,this,env):
            s=str(this); old=args[0] if args else ''; repl=args[1] if len(args)>1 else ''
            if isinstance(old,JSRegExp): return old._re.sub(to_string(repl), s, 0 if 'g' in old.flags else 1)
            return s.replace(to_string(old), to_string(repl), 1)
        return wrap(f)
    if name == 'repeat': return wrap(lambda args,this,env: str(this) * max(0,to_int(args[0]) if args else 0))
    if name == 'padStart': return wrap(lambda args,this,env: str(this).rjust(to_int(args[0]), to_string(args[1])[:1] if len(args)>1 else ' '))
    if name == 'padEnd': return wrap(lambda args,this,env: str(this).ljust(to_int(args[0]), to_string(args[1])[:1] if len(args)>1 else ' '))
    if name in ('toString','valueOf'): return wrap(lambda args,this,env: str(this))
    if name == 'at':
        def f(args,this,env):
            s=str(this); i=to_int(args[0]) if args else 0
            if i<0: i+=len(s)
            return s[i] if 0 <= i < len(s) else UNDEFINED
        return wrap(f)
    return None

def number_method(name):
    def wrap(fn): return native(name, fn)
    if name == 'toString':
        def f(args,this,env):
            radix=to_int(args[0]) if args else 10
            n=int(to_number(this))
            if radix==10: return number_to_string(this)
            digs='0123456789abcdefghijklmnopqrstuvwxyz'; neg=n<0; n=abs(n); s='0' if n==0 else ''
            while n: s=digs[n%radix]+s; n//=radix
            return ('-' if neg else '')+s
        return wrap(f)
    if name == 'toFixed': return wrap(lambda args,this,env: (f"{to_number(this):.{max(0,to_int(args[0]) if args else 0)}f}"))
    if name in ('valueOf',): return wrap(lambda args,this,env: this)
    return None

def regexp_method(name):
    def wrap(fn): return native(name, fn)
    if name == 'test': return wrap(lambda args,this,env: bool(this._re.search(to_string(args[0]) if args else 'undefined')))
    if name == 'exec':
        def f(args,this,env):
            m=this._re.search(to_string(args[0]) if args else 'undefined')
            if not m: return None
            arr=JSArray([m.group(0)] + list(m.groups()))
            arr.props['index']=m.start(); arr.props['input']=to_string(args[0]) if args else 'undefined'
            return arr
        return wrap(f)
    if name == 'toString': return wrap(lambda args,this,env: repr(this))
    return None

