        self.props = OrderedDict()
        if props:
            for k, v in props.items(): self.props[str(k)] = v
        self.class_name = class_name
    def __repr__(self): return f"[object {self.class_name}]"

class JSArray(JSObject):
    def __init__(self, items=None):
        super().__init__(class_name="Array")
        self.items = list(items or [])
    def __repr__(self): return "[" + ", ".join(map(repr, self.items)) + "]"

class JSFunction(JSObject):
    def __init__(self, params=None, body=None, closure=None, name="", native=None, arrow=False, rest=None):
        super().__init__(class_name="Function")
        self.params = params or []
        self.body = body
        self.closure = closure
        self.name = name or ""
        self.native = native
        self.arrow = arrow
        self.rest = rest
        self.props["length"] = len(self.params)
        self.props["name"] = self.name
    def call(self, args, this=UNDEFINED, env=None, construct=False):
        if self.native:
            return self.native(args, this, env)
        call_env = Env(self.closure or env)
        # Arrow functions keep lexical this in real JS.  For this subset the
        # global/received this distinction is sufficient.
        call_env.declare("this", this if not self.arrow else (self.closure.get("this", silent=True) if self.closure else this))
        arr_args = JSArray(args)
        call_env.declare("arguments", arr_args)
        ai = 0
        for p in self.params:
            if p.startswith("..."):
                call_env.declare(p[3:], JSArray(args[ai:]))
                ai = len(args)
            else:
                call_env.declare(p, args[ai] if ai < len(args) else UNDEFINED)
                ai += 1
        try:
            if isinstance(self.body, BlockStmt):
                self.body.exec(call_env)
                return UNDEFINED
            else:
                return self.body.eval(call_env)
        except ReturnSignal as r:
            return r.value
    def __repr__(self): return f"[Function {self.name}]"

class JSErrorObject(JSObject):
    def __init__(self, name="Error", message="", loc=None):
        super().__init__({"name": name, "message": message}, class_name=name)
        self.name = name; self.message = message; self.loc = loc
    def __repr__(self):
        return f"{self.name}: {self.message}" if self.message else self.name

# Control flow / exceptions
class ReturnSignal(Exception):
    def __init__(self, value): self.value = value
class BreakSignal(Exception): pass
class ContinueSignal(Exception): pass
class JSThrown(Exception):
    def __init__(self, value, loc=None): self.value = value; self.loc = loc
class JSSyntax(Exception):
    def __init__(self, msg, token=None): self.msg = msg; self.token = token

# ---------------------------------------------------------------------------
# Conversions and formatting
# ---------------------------------------------------------------------------
def is_undefined(v): return v is UNDEFINED

def is_null(v): return v is None

def is_truthy(v):
    if v is UNDEFINED or v is None: return False
    if isinstance(v, bool): return v
    if isinstance(v, (int, float)): return v != 0 and not (isinstance(v, float) and math.isnan(v))
    if isinstance(v, JSBigInt): return v.value != 0
    if isinstance(v, str): return len(v) > 0
    return True

def to_number(v):
    if v is UNDEFINED: return float('nan')
    if v is None: return 0
    if isinstance(v, bool): return 1 if v else 0
    if isinstance(v, JSBigInt): return v.value
    if isinstance(v, (int, float)): return v
    if isinstance(v, str):
        s = v.strip()
        if s == "": return 0
        try:
            if re.match(r'^[+-]?0[xX][0-9a-fA-F]+$', s): return int(s, 16)
            return float(s)
        except Exception:
            return float('nan')
    return float('nan')

def to_int(v):
    n = to_number(v)
    if isinstance(n, float) and (math.isnan(n) or math.isinf(n)): return 0
    return int(n)

def number_to_string(n):
    if isinstance(n, bool): return "true" if n else "false"
    if isinstance(n, JSBigInt): return str(n.value)
    if isinstance(n, int): return str(n)
    if isinstance(n, float):
        if math.isnan(n): return "NaN"
        if math.isinf(n): return "Infinity" if n > 0 else "-Infinity"
        if n == 0 and math.copysign(1, n) < 0: return "0"
        if n.is_integer(): return str(int(n))
        # close to JS's default for everyday numbers
        s = format(n, '.15g')
        return s
    return str(n)

def to_string(v):
    if v is UNDEFINED: return "undefined"
    if v is None: return "null"
    if isinstance(v, str): return v
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, (int, float, JSBigInt)): return number_to_string(v)
    if isinstance(v, JSArray):
        out = []
        for x in v.items:
            out.append("" if x is UNDEFINED or x is None else to_string(x))
        return ",".join(out)
    if isinstance(v, JSRegExp): return repr(v)
    if isinstance(v, JSFunction):
        return f"function {v.name}() {{ [native code] }}" if v.native else f"function {v.name}() {{ ... }}"
    if isinstance(v, JSErrorObject): return repr(v)
    if isinstance(v, JSObject): return f"[object {v.class_name}]"
    return str(v)

def inspect_js(v, top=False, depth=0):
    if v is UNDEFINED: return "undefined"
    if v is None: return "null"
    if isinstance(v, str):
        if top: return v
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, JSBigInt): return f"{v.value}n"
    if isinstance(v, int): return str(v)
    if isinstance(v, float):
        if math.isnan(v): return "NaN"
        if math.isinf(v): return "Infinity" if v > 0 else "-Infinity"
        if v == 0 and math.copysign(1, v) < 0: return "-0"
        if v.is_integer(): return str(int(v))
        return number_to_string(v)
    if isinstance(v, JSRegExp): return repr(v)
    if isinstance(v, JSFunction): return f"[Function {v.name or 'anonymous'}]"
    if isinstance(v, JSArray):
        if not v.items: return "[]"
        return "[ " + ", ".join(inspect_js(x, False, depth+1) for x in v.items) + " ]"
    if isinstance(v, JSErrorObject): return repr(v)
    if isinstance(v, JSObject):
        if not v.props: return "{}"
        parts = []
        for k, val in v.props.items():
            if k in ("length", "name") and isinstance(v, JSFunction): continue
            parts.append(f"{k}: {inspect_js(val, False, depth+1)}")
        return "{ " + ", ".join(parts) + " }"
    return str(v)

def js_typeof(v):
    if v is UNDEFINED: return "undefined"
    if v is None: return "object"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, JSBigInt): return "bigint"
    if isinstance(v, (int, float)): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, JSFunction): return "function"
    return "object"

def same_value(a, b):
    if a is UNDEFINED or b is UNDEFINED: return a is b
    if a is None or b is None: return a is b
    if type(a) is not type(b): return False
    if isinstance(a, JSBigInt): return a.value == b.value
    return a == b

def loose_equal(a, b):
    if same_value(a, b): return True
    if (a is None and b is UNDEFINED) or (a is UNDEFINED and b is None): return True
    if isinstance(a, bool): return loose_equal(to_number(a), b)
    if isinstance(b, bool): return loose_equal(a, to_number(b))
    if isinstance(a, (int,float,JSBigInt)) and isinstance(b, str): return to_number(a) == to_number(b)
    if isinstance(b, (int,float,JSBigInt)) and isinstance(a, str): return to_number(a) == to_number(b)
    return False

# ---------------------------------------------------------------------------
# Environment
# ---------------------------------------------------------------------------
class Env:
    def __init__(self, parent=None):
        self.parent = parent
        self.vars = OrderedDict()
    def declare(self, name, value=UNDEFINED):
        self.vars[name] = value
        return value
    def has_local(self, name): return name in self.vars
    def has(self, name):
        return name in self.vars or (self.parent.has(name) if self.parent else False)
    def get(self, name, silent=False):
        if name in self.vars: return self.vars[name]
        if self.parent: return self.parent.get(name, silent=silent)
        if silent: return UNDEFINED
        raise JSThrown(JSErrorObject("ReferenceError", f"'{name}' is not defined"))
    def set(self, name, value):
        if name in self.vars:
            self.vars[name] = value; return value
        if self.parent and self.parent.has(name): return self.parent.set(name, value)
        # non-strict assignment creates a global
        root = self
        while root.parent: root = root.parent
        root.vars[name] = value
        return value

# ---------------------------------------------------------------------------
# Lexer
# ---------------------------------------------------------------------------
KEYWORDS = set("break case catch class const continue debugger default delete do else export extends false finally for function if import in instanceof let new null return super switch this throw true try typeof undefined var void while with yield async await of static get set from as".split())
MULTI_OPS = ["===", "!==", ">>>=", "<<=", ">>=", "**=", "=>", "...", "++", "--", "&&", "||", "??", "<=", ">=", "==", "!=", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>>", ">>", "**", "?."]
SINGLE = set("{}()[];,.?:+-*/%<>=!~&|^")

class Token:
    def __init__(self, typ, val, line, col):
        self.typ = typ; self.val = val; self.line = line; self.col = col
    def __repr__(self): return f"Token({self.typ},{self.val!r},{self.line}:{self.col})"

class Lexer:
    def __init__(self, src):
        self.src = src; self.i = 0; self.line = 1; self.col = 1; self.n = len(src)
        self.tokens = []
    def peek(self, k=0):
        j = self.i + k
        return self.src[j] if j < self.n else ''
    def adv(self):
        ch = self.peek(); self.i += 1
        if ch == '\n': self.line += 1; self.col = 1
        else: self.col += 1
        return ch
    def add(self, typ, val, line, col): self.tokens.append(Token(typ, val, line, col))
    def skip_ws_comments(self):
        while True:
            ch = self.peek()
            if ch and ch.isspace(): self.adv(); continue
            if ch == '/' and self.peek(1) == '/':
                while self.peek() and self.peek() != '\n': self.adv()
                continue
            if ch == '/' and self.peek(1) == '*':
                self.adv(); self.adv()
                while self.peek() and not (self.peek() == '*' and self.peek(1) == '/'):
                    self.adv()
                if self.peek(): self.adv(); self.adv()
                continue
            break
    def lex_string(self, quote):
        line, col = self.line, self.col
        self.adv(); out = []
        while self.peek():
            ch = self.adv()
            if ch == quote: break
            if ch == '\\':
                e = self.adv()
                maps = {'n':'\n','r':'\r','t':'\t','b':'\b','f':'\f','v':'\v','0':'\0'}
                if e in maps: out.append(maps[e])
                elif e == 'x':
                    hx = self.adv()+self.adv()
                    try: out.append(chr(int(hx,16)))
                    except Exception: out.append('')
                elif e == 'u':
                    if self.peek() == '{':
                        self.adv(); hx=''
                        while self.peek() and self.peek()!='}': hx += self.adv()
                        if self.peek()=='}': self.adv()
                        try: out.append(chr(int(hx,16)))
                        except Exception: pass
                    else:
                        hx = ''.join(self.adv() for _ in range(4))
                        try: out.append(chr(int(hx,16)))
                        except Exception: pass
                elif e == '\n': pass
                else: out.append(e)
            else: out.append(ch)
        self.add('string', ''.join(out), line, col)
    def lex_template(self):
        line, col = self.line, self.col
        self.adv(); out=[]
        while self.peek():
            ch = self.adv()
            if ch == '`': break
            if ch == '\\':
                e = self.adv(); maps={'n':'\n','r':'\r','t':'\t','`':'`','$':'$'}; out.append(maps.get(e,e))
            else: out.append(ch)
        self.add('template', ''.join(out), line, col)
    def lex_number(self):
        line, col = self.line, self.col
        s = ''
        if self.peek() == '0' and self.peek(1) in 'xX':
            s += self.adv()+self.adv()
            while re.match(r'[0-9a-fA-F_]', self.peek() or ''): s += self.adv()
        elif self.peek() == '0' and self.peek(1) in 'bB':
            s += self.adv()+self.adv()
            while self.peek() in '01_': s += self.adv()
        elif self.peek() == '0' and self.peek(1) in 'oO':
            s += self.adv()+self.adv()
            while self.peek() in '01234567_': s += self.adv()
        else:
            while self.peek().isdigit() or self.peek() == '_': s += self.adv()
            if self.peek() == '.':
                s += self.adv()
                while self.peek().isdigit() or self.peek() == '_': s += self.adv()
            if self.peek() in 'eE':
                s += self.adv()
                if self.peek() in '+-': s += self.adv()
                while self.peek().isdigit() or self.peek() == '_': s += self.adv()
        if self.peek() == 'n':
            self.adv(); self.add('bigint', s.replace('_',''), line, col)
        else:
            self.add('number', s.replace('_',''), line, col)
    def lex_ident(self):
        line, col = self.line, self.col
        s = ''
        while True:
            ch = self.peek()
            if ch and (ch.isalnum() or ch in '_$'):
                s += self.adv()
            else: break
        self.add('ident', s, line, col)
    def maybe_regex(self):
        # Simple heuristic for regex literal after an expression-start token.
        prev = None
        for t in reversed(self.tokens):
            if t.typ != 'eof': prev = t; break
        if prev and (prev.typ in ('number','string','ident','bigint') or prev.val in (')',']')):
            return False
        return True
    def lex_regex(self):
        line,col = self.line,self.col
        self.adv(); pat=''; in_class=False
        while self.peek():
            ch=self.adv()
            if ch=='\\': pat += ch + self.adv(); continue
            if ch=='[': in_class=True
            elif ch==']': in_class=False
            elif ch=='/' and not in_class: break
            pat += ch
        flags=''
        while self.peek().isalpha(): flags += self.adv()
        self.add('regex', (pat,flags), line,col)
    def run(self):
        while self.i < self.n:
            self.skip_ws_comments()
            if self.i >= self.n: break
            ch = self.peek(); line, col = self.line, self.col
            if ch in ('"', "'"):
                self.lex_string(ch); continue
            if ch == '`': self.lex_template(); continue
            if ch.isdigit() or (ch == '.' and self.peek(1).isdigit()):
                if ch == '.':
                    # leading decimal
                    self.add('number', '0', line, col)  # not used; handle by normal path via prep not worth complexity
                self.lex_number(); continue
            if ch.isalpha() or ch in '_$': self.lex_ident(); continue
            if ch == '/' and self.peek(1) not in ('/','*') and self.maybe_regex():
                self.lex_regex(); continue
            matched = False
            for op in MULTI_OPS:
                if self.src.startswith(op, self.i):
                    self.add('op', op, line, col)
                    for _ in op: self.adv()
                    matched=True; break
            if matched: continue
            if ch in SINGLE:
                self.add('op', ch, line, col); self.adv(); continue
            # Unknown character: emit and advance, parser will complain
            self.add('op', ch, line, col); self.adv()
        self.tokens.append(Token('eof','<eof>', self.line, self.col))
        return self.tokens

# ---------------------------------------------------------------------------
# AST nodes
# ---------------------------------------------------------------------------
class Node: pass
class Expr(Node):
    def eval(self, env): return UNDEFINED
class Stmt(Node):
    def exec(self, env): return UNDEFINED

class Program(Stmt):
    def __init__(self, stmts): self.stmts=stmts
    def exec(self, env):
        hoist_functions(self.stmts, env)
        res = UNDEFINED
        for s in self.stmts:
            if isinstance(s, FunctionDecl): continue
            res = s.exec(env)
        return res

class BlockStmt(Stmt):
    def __init__(self, stmts): self.stmts=stmts
    def exec(self, env):
        hoist_functions(self.stmts, env)
        res=UNDEFINED
        for s in self.stmts:
            if isinstance(s, FunctionDecl): continue
            res=s.exec(env)
        return res

def hoist_functions(stmts, env):
    for s in stmts:
        if isinstance(s, FunctionDecl):
            env.declare(s.name, JSFunction(s.params, s.body, env, s.name, rest=s.rest))

class EmptyStmt(Stmt):
    def exec(self, env): return UNDEFINED
class ExprStmt(Stmt):
    def __init__(self, expr): self.expr=expr
    def exec(self, env): return self.expr.eval(env)
class VarDeclStmt(Stmt):
    def __init__(self, decls): self.decls=decls
    def exec(self, env):
        val=UNDEFINED
        for name, init in self.decls:
            val = init.eval(env) if init else UNDEFINED
            if env.has_local(name): env.set(name, val)
            else: env.declare(name, val)
        return val
class FunctionDecl(Stmt):
    def __init__(self, name, params, body, rest=None): self.name=name; self.params=params; self.body=body; self.rest=rest
    def exec(self, env): env.declare(self.name, JSFunction(self.params,self.body,env,self.name,rest=self.rest)); return UNDEFINED
class ReturnStmt(Stmt):
    def __init__(self, expr=None): self.expr=expr
    def exec(self, env): raise ReturnSignal(self.expr.eval(env) if self.expr else UNDEFINED)
class BreakStmt(Stmt):
    def exec(self, env): raise BreakSignal()
class ContinueStmt(Stmt):
    def exec(self, env): raise ContinueSignal()
class IfStmt(Stmt):
    def __init__(self, test, cons, alt=None): self.test=test; self.cons=cons; self.alt=alt
    def exec(self, env): return self.cons.exec(env) if is_truthy(self.test.eval(env)) else (self.alt.exec(env) if self.alt else UNDEFINED)
class WhileStmt(Stmt):
    def __init__(self, test, body): self.test=test; self.body=body
    def exec(self, env):
        res=UNDEFINED
        while is_truthy(self.test.eval(env)):
            try: res=self.body.exec(env)
            except ContinueSignal: continue
            except BreakSignal: break
        return res
class DoWhileStmt(Stmt):
    def __init__(self, body, test): self.body=body; self.test=test
    def exec(self, env):
        res=UNDEFINED
        while True:
            try: res=self.body.exec(env)
            except ContinueSignal: pass
            except BreakSignal: break
            if not is_truthy(self.test.eval(env)): break
        return res
class ForStmt(Stmt):
    def __init__(self, init, test, update, body): self.init=init; self.test=test; self.update=update; self.body=body
    def exec(self, env):
        res=UNDEFINED
        if self.init:
            if isinstance(self.init, Stmt): self.init.exec(env)
            else: self.init.eval(env)
        while True:
            if self.test and not is_truthy(self.test.eval(env)): break
            try: res=self.body.exec(env)
            except ContinueSignal: pass
            except BreakSignal: break
            if self.update: self.update.eval(env)
        return res
class ForOfStmt(Stmt):
    def __init__(self, target, iterable, body, is_decl=False): self.target=target; self.iterable=iterable; self.body=body; self.is_decl=is_decl
    def exec(self, env):
        it = self.iterable.eval(env)
        seq=[]
        if isinstance(it, JSArray): seq = it.items
        elif isinstance(it, str): seq = list(it)
        elif isinstance(it, JSObject): seq = list(it.props.keys())
        res=UNDEFINED
        for val in seq:
            assign_target(self.target, val, env, declare=self.is_decl)
            try: res=self.body.exec(env)
            except ContinueSignal: continue
            except BreakSignal: break
        return res
class ThrowStmt(Stmt):
    def __init__(self, expr, token=None): self.expr=expr; self.token=token
    def exec(self, env): raise JSThrown(self.expr.eval(env), self.token)
class TryStmt(Stmt):
    def __init__(self, block, catch_name, catch_block, finally_block):
        self.block=block; self.catch_name=catch_name; self.catch_block=catch_block; self.finally_block=finally_block
    def exec(self, env):
        res=UNDEFINED
        try: res=self.block.exec(env)
        except JSThrown as e:
            if self.catch_block:
                cenv=Env(env); cenv.declare(self.catch_name or "e", e.value)
                res=self.catch_block.exec(cenv)
            else: raise
        finally:
            if self.finally_block: res=self.finally_block.exec(env)
        return res
class ImportStmt(Stmt):
    def __init__(self, specs, module_name, token=None): self.specs=specs; self.module_name=module_name; self.token=token
    def exec(self, env):
        mod = load_module_object(self.module_name, env)
        for typ, imported, local in self.specs:
            if typ == 'namespace': env.declare(local, mod)
            elif typ == 'named': env.declare(local, get_prop(mod, imported))
            elif typ == 'default':
                raise JSThrown(JSErrorObject("SyntaxError", f"Could not find export 'default' in module '{self.module_name}'"))
        return UNDEFINED
class SwitchStmt(Stmt):
    def __init__(self, expr, cases): self.expr=expr; self.cases=cases
    def exec(self, env):
        val=self.expr.eval(env); start=None; default=None
        for i,(caseexpr,stmts) in enumerate(self.cases):
            if caseexpr is None: default=i
            elif same_value(val, caseexpr.eval(env)): start=i; break
        if start is None: start=default
        res=UNDEFINED
        if start is not None:
            try:
                for _,stmts in self.cases[start:]:
                    for s in stmts: res=s.exec(env)
            except BreakSignal: pass
        return res

# Expressions
class Literal(Expr):
    def __init__(self, value): self.value=value
    def eval(self, env): return self.value
class TemplateLiteral(Expr):
    def __init__(self, raw, parser_source_name='<template>'): self.raw=raw; self.source=parser_source_name
    def eval(self, env):
        s=self.raw; out=''; i=0
        while i < len(s):
            j=s.find('${', i)
            if j < 0: out += s[i:]; break
            out += s[i:j]; k=j+2; depth=1; q=None
            while k < len(s) and depth:
                ch=s[k]
                if q:
                    if ch=='\\': k += 2; continue
                    if ch==q: q=None
                else:
                    if ch in ('"',"'",'`'): q=ch
                    elif ch=='{': depth+=1
                    elif ch=='}': depth-=1
                k+=1
            exprsrc=s[j+2:k-1]
            try: val=Parser(Lexer(exprsrc).run(), self.source, True).parse_expression().eval(env)
            except Exception: val=UNDEFINED
            out += to_string(val); i=k
        return out
class Var(Expr):
    def __init__(self, name, token=None): self.name=name; self.token=token
    def eval(self, env):
        if self.name == 'undefined': return UNDEFINED
        return env.get(self.name)
class ThisExpr(Expr):
    def eval(self, env): return env.get('this', silent=True)
class ArrayLit(Expr):
    def __init__(self, elems): self.elems=elems
    def eval(self, env):
        arr=[]
        for spread, e in self.elems:
            v=e.eval(env)
            if spread:
                if isinstance(v, JSArray): arr.extend(v.items)
                elif isinstance(v, str): arr.extend(list(v))
            else: arr.append(v)
        return JSArray(arr)
class ObjectLit(Expr):
    def __init__(self, props): self.props=props
    def eval(self, env):
        obj=JSObject()
        for keyexpr, valexpr, kind in self.props:
            if kind == 'spread':
                v=valexpr.eval(env)
                if isinstance(v, JSObject):
                    for k,val in v.props.items(): obj.props[k]=val
                continue
            key = keyexpr.eval(env) if isinstance(keyexpr, Expr) else keyexpr
            obj.props[str(key)] = valexpr.eval(env)
        return obj
class FunctionExpr(Expr):
    def __init__(self, params, body, name="", arrow=False, rest=None): self.params=params; self.body=body; self.name=name; self.arrow=arrow; self.rest=rest
    def eval(self, env): return JSFunction(self.params, self.body, env, self.name, arrow=self.arrow, rest=self.rest)
class Member(Expr):
    def __init__(self, obj, prop, computed=False, optional=False): self.obj=obj; self.prop=prop; self.computed=computed; self.optional=optional
    def ref(self, env):
        o=self.obj.eval(env)
        if self.optional and (o is UNDEFINED or o is None): return (UNDEFINED, None)
        p=self.prop.eval(env) if self.computed else self.prop
        return (o, p)
    def eval(self, env):
        o,p=self.ref(env)
        if p is None: return UNDEFINED
        return get_prop(o,p)
class Call(Expr):
    def __init__(self, callee, args, token=None, is_new=False): self.callee=callee; self.args=args; self.token=token; self.is_new=is_new
    def eval(self, env):
        args=[]
        for spread, a in self.args:
            v=a.eval(env)
            if spread and isinstance(v, JSArray): args.extend(v.items)
            else: args.append(v)
        this=UNDEFINED
        fn=None
        if isinstance(self.callee, Member):
            this, prop = self.callee.ref(env)
            fn = UNDEFINED if prop is None else get_prop(this, prop)
        else: fn = self.callee.eval(env)
        if not isinstance(fn, JSFunction):
            raise JSThrown(JSErrorObject("TypeError", "not a function"), self.token)
        return fn.call(args, this, env, construct=self.is_new)
class NewExpr(Expr):
    def __init__(self, callee, args, token=None): self.callee=callee; self.args=args; self.token=token
    def eval(self, env): return Call(self.callee, self.args, self.token, True).eval(env)
class Unary(Expr):
    def __init__(self, op, expr, token=None): self.op=op; self.expr=expr; self.token=token
    def eval(self, env):
        if self.op == 'typeof':
            if isinstance(self.expr, Var): return js_typeof(env.get(self.expr.name, silent=True))
            try: return js_typeof(self.expr.eval(env))
            except JSThrown: return 'undefined'
        if self.op == 'void': self.expr.eval(env); return UNDEFINED
        if self.op == 'delete': return True
        v=self.expr.eval(env)
        if self.op == '!': return not is_truthy(v)
        if self.op == '+': return to_number(v)
        if self.op == '-':
            if isinstance(v, JSBigInt): return JSBigInt(-v.value)
            n=to_number(v); return -n
        if self.op == '~': return ~to_int(v)
        if self.op == '++':
            cur=to_number(v); nv=cur+1; assign_target(self.expr,nv,env); return nv
        if self.op == '--':
            cur=to_number(v); nv=cur-1; assign_target(self.expr,nv,env); return nv
        return UNDEFINED
class Postfix(Expr):
    def __init__(self, expr, op): self.expr=expr; self.op=op
    def eval(self, env):
        old=self.expr.eval(env); nv=to_number(old)+(1 if self.op=='++' else -1); assign_target(self.expr,nv,env); return old
class Binary(Expr):
    def __init__(self, op, left, right): self.op=op; self.left=left; self.right=right
    def eval(self, env):
        op=self.op
        if op == '&&':
            l=self.left.eval(env); return self.right.eval(env) if is_truthy(l) else l
        if op == '||':
            l=self.left.eval(env); return l if is_truthy(l) else self.right.eval(env)
        if op == '??':
            l=self.left.eval(env); return self.right.eval(env) if (l is UNDEFINED or l is None) else l
        l=self.left.eval(env); r=self.right.eval(env)
        if op == '+':
            if isinstance(l, JSBigInt) and isinstance(r, JSBigInt): return JSBigInt(l.value+r.value)
            if isinstance(l, str) or isinstance(r, str) or isinstance(l, JSObject) or isinstance(r, JSObject): return to_string(l)+to_string(r)
            return to_number(l)+to_number(r)
        if op == '-':
            if isinstance(l, JSBigInt) and isinstance(r, JSBigInt): return JSBigInt(l.value-r.value)
            return to_number(l)-to_number(r)
        if op == '*':
            if isinstance(l, JSBigInt) and isinstance(r, JSBigInt): return JSBigInt(l.value*r.value)
            return to_number(l)*to_number(r)
        if op == '/':
            try: return to_number(l)/to_number(r)
            except ZeroDivisionError:
                n=to_number(l); d=to_number(r)
                if n == 0: return float('nan')
                return math.copysign(float('inf'), n*d if d else n)
        if op == '%':
            try: return math.fmod(to_number(l), to_number(r))
            except Exception: return float('nan')
        if op == '**': return to_number(l) ** to_number(r)
        if op in ('==','!=','===','!=='):
            eq = same_value(l,r) if op in ('===','!==') else loose_equal(l,r)
            return (not eq) if op in ('!=','!==') else eq
        if op in ('<','>','<=','>='):
            if isinstance(l,str) and isinstance(r,str):
                return {'<':l<r,'>':l>r,'<=':l<=r,'>=':l>=r}[op]
            ln=to_number(l); rn=to_number(r)
            return {'<':ln<rn,'>':ln>rn,'<=':ln<=rn,'>=':ln>=rn}[op]
        if op == 'in':
            if isinstance(r, JSArray) and str(l).isdigit(): return int(l) < len(r.items)
            if isinstance(r, JSObject): return str(l) in r.props
            return False
        if op == 'instanceof': return False
        if op == '&': return to_int(l)&to_int(r)
        if op == '|': return to_int(l)|to_int(r)
        if op == '^': return to_int(l)^to_int(r)
        if op == '<<': return to_int(l)<< (to_int(r)&31)
        if op == '>>': return to_int(l)>> (to_int(r)&31)
        if op == '>>>': return (to_int(l) & 0xffffffff) >> (to_int(r)&31)
        return UNDEFINED
class Conditional(Expr):
    def __init__(self, t,c,a): self.t=t; self.c=c; self.a=a
    def eval(self, env): return self.c.eval(env) if is_truthy(self.t.eval(env)) else self.a.eval(env)
class Assign(Expr):
    def __init__(self, left, op, right): self.left=left; self.op=op; self.right=right
    def eval(self, env):
        if self.op == '=': val=self.right.eval(env)
        else:
            cur=self.left.eval(env); rhs=self.right.eval(env); val=Binary(self.op[:-1], Literal(cur), Literal(rhs)).eval(env)
        assign_target(self.left, val, env)
        return val
class Sequence(Expr):
    def __init__(self, exprs): self.exprs=exprs
    def eval(self, env):
        val=UNDEFINED
        for e in self.exprs: val=e.eval(env)
        return val

# ---------------------------------------------------------------------------
# Parser
# ---------------------------------------------------------------------------
PRECEDENCE = {
    '||':3, '??':3, '&&':4, '|':5, '^':6, '&':7,
    '==':8, '!=':8, '===':8, '!==':8,
    '<':9, '>':9, '<=':9, '>=':9, 'in':9, 'instanceof':9,
    '<<':10, '>>':10, '>>>':10,
    '+':11, '-':11,
    '*':12, '/':12, '%':12,
    '**':13,
}
ASSIGN_OPS = set(['=','+=','-=','*=','/=','%=','**=','<<=','>>=','>>>=','&=','|=','^='])

class Parser:
    def __init__(self, tokens, source_name='<cmdline>', module=False):
        self.tokens=tokens; self.i=0; self.source_name=source_name; self.module=module
    def cur(self): return self.tokens[self.i]
    def peek(self,k=1): return self.tokens[min(self.i+k,len(self.tokens)-1)]
    def at(self, val): return self.cur().val == val
    def match(self, val):
        if self.at(val): self.i+=1; return True
        return False
    def expect(self, val, msg=None):
        if not self.match(val): raise JSSyntax(msg or f"expecting '{val}'", self.cur())
        return self.tokens[self.i-1]
    def consume_semicolon(self):
        if self.match(';'): return
        if self.cur().typ != 'eof' and not self.at('}'):
            # permissive ASI; leave token for constructs, but two bare identifiers should fail like qjs
            pass
    def parse_program(self):
        stmts=[]
        while self.cur().typ!='eof':
            if self.match(';'): continue
            stmts.append(self.parse_statement())
        return Program(stmts)
    def parse_statement(self):
        t=self.cur(); v=t.val
        if v == '{': return self.parse_block()
        if v in ('var','let','const'): return self.parse_var_decl_statement()
        if v == 'function': return self.parse_function_decl()
        if v == 'if': return self.parse_if()
        if v == 'while': return self.parse_while()
        if v == 'do': return self.parse_do_while()
        if v == 'for': return self.parse_for()
        if v == 'return':
            self.i+=1
            expr=None if self.at(';') or self.at('}') or self.cur().typ=='eof' else self.parse_expression()
            self.consume_semicolon(); return ReturnStmt(expr)
        if v == 'break': self.i+=1; self.consume_semicolon(); return BreakStmt()
        if v == 'continue': self.i+=1; self.consume_semicolon(); return ContinueStmt()
        if v == 'throw':
            tok=self.cur(); self.i+=1; expr=self.parse_expression(); self.consume_semicolon(); return ThrowStmt(expr,tok)
        if v == 'try': return self.parse_try()
        if v == 'switch': return self.parse_switch()
        if v == 'import':
            if not self.module:
                # QuickJS script parser complains near the token after import.
                raise JSSyntax("expecting '('", self.peek())
            return self.parse_import()
        if v == 'export':
            # Basic module export support: execute declaration normally.
            self.i+=1
            if self.cur().val in ('var','let','const'): return self.parse_var_decl_statement()
            if self.cur().val == 'function': return self.parse_function_decl()
            if self.match('{'):
                while not self.match('}') and self.cur().typ!='eof': self.i+=1
                self.consume_semicolon(); return EmptyStmt()
        expr=self.parse_expression()
        if self.cur().typ not in ('eof',) and not self.at(';') and not self.at('}'):
            # common syntax error: two expressions without separator
            raise JSSyntax("expecting ';'", self.cur())
        self.consume_semicolon(); return ExprStmt(expr)
    def parse_block(self):
        self.expect('{'); stmts=[]
        while not self.at('}') and self.cur().typ!='eof':
            if self.match(';'): continue
            stmts.append(self.parse_statement())
        self.expect('}'); return BlockStmt(stmts)
    def parse_var_decl_statement(self):
        decls=self.parse_var_decls()
        self.consume_semicolon(); return VarDeclStmt(decls)
    def parse_var_decls(self):
        self.i+=1 # kind
        decls=[]
        while True:
            if self.cur().typ!='ident': raise JSSyntax("expected variable name", self.cur())
            name=self.cur().val; self.i+=1; init=None
            if self.match('='): init=self.parse_assignment()
            decls.append((name, init))
            if not self.match(','): break
        return decls
    def parse_function_decl(self):
        self.expect('function')
        if self.match('*'): pass
        if self.cur().typ!='ident': raise JSSyntax("expected function name", self.cur())
        name=self.cur().val; self.i+=1
        params, rest = self.parse_params()
        body=self.parse_block()
        return FunctionDecl(name, params, body, rest)
    def parse_params(self):
        self.expect('('); params=[]; rest=None
        if not self.at(')'):
            while True:
                if self.match('...'):
                    if self.cur().typ!='ident': raise JSSyntax("expected parameter name", self.cur())
                    rest='...'+self.cur().val; params.append(rest); self.i+=1
                else:
                    if self.cur().typ!='ident': raise JSSyntax("expected parameter name", self.cur())
                    params.append(self.cur().val); self.i+=1
                    if self.match('='):
                        self.parse_assignment()  # default ignored; consumes expression
                if not self.match(','): break
        self.expect(')'); return params, rest
    def parse_if(self):
        self.expect('if'); self.expect('('); test=self.parse_expression(); self.expect(')')
        cons=self.parse_statement(); alt=None
        if self.match('else'): alt=self.parse_statement()
        return IfStmt(test,cons,alt)
    def parse_while(self):
        self.expect('while'); self.expect('('); test=self.parse_expression(); self.expect(')'); return WhileStmt(test,self.parse_statement())
    def parse_do_while(self):
        self.expect('do'); body=self.parse_statement(); self.expect('while'); self.expect('('); test=self.parse_expression(); self.expect(')'); self.consume_semicolon(); return DoWhileStmt(body,test)
    def parse_for(self):
        self.expect('for'); self.expect('(')
        if self.match(';'):
            init=None
        elif self.cur().val in ('var','let','const'):
            kindtok=self.cur(); self.i+=1
            if self.cur().typ!='ident': raise JSSyntax("expected variable name", self.cur())
            name=self.cur().val; self.i+=1; initexpr=None
            if self.match('='): initexpr=self.parse_assignment()
            if self.cur().val in ('of','in'):
                self.i+=1; iterable=self.parse_expression(); self.expect(')')
                return ForOfStmt(Var(name), iterable, self.parse_statement(), True)
            decls=[(name, initexpr)]
            while self.match(','):
                if self.cur().typ!='ident': raise JSSyntax("expected variable name", self.cur())
                n=self.cur().val; self.i+=1; ie=None
                if self.match('='): ie=self.parse_assignment()
                decls.append((n,ie))
            init=VarDeclStmt(decls); self.expect(';')
        else:
            init=self.parse_expression()
            if self.cur().val in ('of','in'):
                self.i+=1; iterable=self.parse_expression(); self.expect(')')
                return ForOfStmt(init, iterable, self.parse_statement(), False)
            self.expect(';')
        test=None if self.at(';') else self.parse_expression(); self.expect(';')
        update=None if self.at(')') else self.parse_expression(); self.expect(')')
        return ForStmt(init,test,update,self.parse_statement())
    def parse_try(self):
        self.expect('try'); block=self.parse_block(); cname=None; cblock=None; fblock=None
        if self.match('catch'):
            if self.match('('):
                if self.cur().typ=='ident': cname=self.cur().val; self.i+=1
                self.expect(')')
            cblock=self.parse_block()
        if self.match('finally'): fblock=self.parse_block()
        return TryStmt(block,cname,cblock,fblock)
    def parse_switch(self):
        self.expect('switch'); self.expect('('); expr=self.parse_expression(); self.expect(')'); self.expect('{')
        cases=[]
        while not self.at('}') and self.cur().typ!='eof':
            ce=None
            if self.match('case'): ce=self.parse_expression(); self.expect(':')
            elif self.match('default'): self.expect(':')
            else: raise JSSyntax("expecting 'case'", self.cur())
            stmts=[]
            while not self.at('case') and not self.at('default') and not self.at('}') and self.cur().typ!='eof': stmts.append(self.parse_statement())
            cases.append((ce,stmts))
        self.expect('}'); return SwitchStmt(expr,cases)
    def parse_import(self):
        tok=self.expect('import'); specs=[]
        if self.cur().typ=='string':
            mod=self.cur().val; self.i+=1; self.consume_semicolon(); return ImportStmt(specs,mod,tok)
        if self.match('*'):
            self.expect('as')
            local=self.cur().val; self.i+=1; specs.append(('namespace',None,local))
        elif self.match('{'):
            while not self.match('}'):
                if self.cur().typ!='ident': raise JSSyntax("expected import name", self.cur())
                imp=self.cur().val; self.i+=1; loc=imp
                if self.match('as'):
                    loc=self.cur().val; self.i+=1
                specs.append(('named',imp,loc))
                self.match(',')
        else:
            if self.cur().typ=='ident':
                loc=self.cur().val; self.i+=1; specs.append(('default','default',loc))
            else: raise JSSyntax("invalid import", self.cur())
        self.expect('from')
        if self.cur().typ!='string': raise JSSyntax("expected module name", self.cur())
        mod=self.cur().val; self.i+=1; self.consume_semicolon(); return ImportStmt(specs,mod,tok)
    def parse_expression(self):
        exprs=[self.parse_assignment()]
        while self.match(','):
            exprs.append(self.parse_assignment())
        return exprs[0] if len(exprs)==1 else Sequence(exprs)
    def is_arrow_start(self):
        if self.cur().typ=='ident' and self.peek().val=='=>': return True
        if not self.at('('): return False
        depth=0; j=self.i
        while j < len(self.tokens):
            v=self.tokens[j].val
            if v=='(': depth+=1
            elif v==')':
                depth-=1
                if depth==0: return self.tokens[j+1].val=='=>' if j+1 < len(self.tokens) else False
            j+=1
        return False
    def parse_arrow(self):
        params=[]; rest=None
        if self.cur().typ=='ident':
            params=[self.cur().val]; self.i+=1
        else:
            self.expect('(')
            if not self.at(')'):
                while True:
                    if self.match('...'):
                        rest='...'+self.cur().val; params.append(rest); self.i+=1
                    else:
                        if self.cur().typ!='ident': raise JSSyntax("expected parameter name", self.cur())
                        params.append(self.cur().val); self.i+=1
                        if self.match('='): self.parse_assignment()
                    if not self.match(','): break
            self.expect(')')
        self.expect('=>')
        body=self.parse_block() if self.at('{') else self.parse_assignment()
        return FunctionExpr(params, body, arrow=True, rest=rest)
    def parse_assignment(self):
        if self.is_arrow_start(): return self.parse_arrow()
        left=self.parse_conditional()
        if self.cur().val in ASSIGN_OPS:
            op=self.cur().val; self.i+=1; right=self.parse_assignment(); return Assign(left,op,right)
        return left
    def parse_conditional(self):
        expr=self.parse_binary(0)
        if self.match('?'):
            cons=self.parse_expression(); self.expect(':'); alt=self.parse_assignment(); return Conditional(expr,cons,alt)
        return expr
    def parse_binary(self, minprec):
        left=self.parse_unary()
        while True:
            op=self.cur().val
            if op not in PRECEDENCE or PRECEDENCE[op] < minprec: break
            prec=PRECEDENCE[op]; self.i+=1
            nextmin = prec if op=='**' else prec+1
            right=self.parse_binary(nextmin)
            left=Binary(op,left,right)
        return left
    def parse_unary(self):
        t=self.cur(); op=t.val
        if op in ('!','~','+','-','typeof','void','delete','++','--'):
            self.i+=1; return Unary(op,self.parse_unary(),t)
        if op == 'new':
            self.i+=1; callee=self.parse_postfix(base_only=True); args=[]
            if self.at('('): args=self.parse_args()
            return NewExpr(callee,args,t)
        return self.parse_postfix()
    def parse_postfix(self, base_only=False):
        expr=self.parse_primary()
        while True:
            if self.match('.'):
                if self.cur().typ!='ident': raise JSSyntax("expected property name", self.cur())
                p=self.cur().val; self.i+=1; expr=Member(expr,p,False)
            elif self.match('?.'):
                if self.match('('):
                    args=self.parse_args(already_open=True); expr=Call(expr,args)
                else:
                    if self.match('.'):
                        pass
                    if self.cur().typ!='ident': raise JSSyntax("expected property name", self.cur())
                    p=self.cur().val; self.i+=1; expr=Member(expr,p,False,True)
            elif self.match('['):
                p=self.parse_expression(); self.expect(']'); expr=Member(expr,p,True)
            elif self.at('('):
                args=self.parse_args(); expr=Call(expr,args,self.cur())
            else: break
            if base_only: break
        if self.cur().val in ('++','--'):
            op=self.cur().val; self.i+=1; expr=Postfix(expr,op)
        return expr
    def parse_args(self, already_open=False):
        if not already_open: self.expect('(')
        args=[]
        if not self.at(')'):
            while True:
                spread=self.match('...')
                args.append((spread,self.parse_assignment()))
                if not self.match(','): break
        self.expect(')'); return args
    def parse_primary(self):
        t=self.cur(); v=t.val
        if t.typ=='number':
            self.i+=1
            s=v
            try:
                if s.lower().startswith('0x'): return Literal(int(s,16))
                if s.lower().startswith('0b'): return Literal(int(s,2))
                if s.lower().startswith('0o'): return Literal(int(s,8))
                return Literal(float(s) if ('.' in s or 'e' in s.lower()) else int(s))
            except Exception: return Literal(float('nan'))
        if t.typ=='bigint':
            self.i+=1
            s=v
            try:
                if s.lower().startswith('0x'): val=int(s,16)
                elif s.lower().startswith('0b'): val=int(s,2)
                elif s.lower().startswith('0o'): val=int(s,8)
                else: val=int(s)
            except Exception: val=0
            return Literal(JSBigInt(val))
        if t.typ=='string': self.i+=1; return Literal(v)
        if t.typ=='template': self.i+=1; return TemplateLiteral(v,self.source_name)
        if t.typ=='regex': self.i+=1; return Literal(JSRegExp(v[0],v[1]))
        if v=='true': self.i+=1; return Literal(True)
        if v=='false': self.i+=1; return Literal(False)
        if v=='null': self.i+=1; return Literal(None)
        if v=='undefined': self.i+=1; return Literal(UNDEFINED)
        if v=='this': self.i+=1; return ThisExpr()
        if v=='function': return self.parse_function_expr()
        if v=='(':
            self.i+=1; expr=self.parse_expression(); self.expect(')'); return expr
        if v=='[': return self.parse_array_lit()
        if v=='{': return self.parse_object_lit()
        if t.typ=='ident': self.i+=1; return Var(v,t)
        raise JSSyntax(f"unexpected token in expression: '{v}'", t)
    def parse_function_expr(self):
        self.expect('function')
        if self.match('*'): pass
        name=""
        if self.cur().typ=='ident': name=self.cur().val; self.i+=1
        params, rest=self.parse_params(); body=self.parse_block(); return FunctionExpr(params,body,name,False,rest)
    def parse_array_lit(self):
        self.expect('['); elems=[]
        while not self.at(']') and self.cur().typ!='eof':
            if self.match(','):
                elems.append((False,Literal(UNDEFINED))); continue
            spread=self.match('...')
            elems.append((spread,self.parse_assignment()))
            if not self.match(','): break
        self.expect(']'); return ArrayLit(elems)
    def parse_object_lit(self):
        self.expect('{'); props=[]
        while not self.at('}') and self.cur().typ!='eof':
            if self.match('...'):
                props.append((None,self.parse_assignment(),'spread'))
            else:
                computed=False
                if self.match('['):
                    key=self.parse_expression(); self.expect(']'); computed=True
                else:
                    if self.cur().typ in ('ident','string','number'):
                        key=self.cur().val; self.i+=1
                    else: raise JSSyntax("expected property name", self.cur())
                if self.match(':'):
                    val=self.parse_assignment()
                elif self.at('('):
                    # method shorthand
