def prop_key(p):
    if isinstance(p, JSBigInt): return str(p.value)
    if isinstance(p, (int,float)) and not isinstance(p,bool):
        if isinstance(p,float) and p.is_integer(): return str(int(p))
    return to_string(p)

def get_prop(obj, prop):
