def string_method(name):
    def wrap(fn): return native(name, fn)
    if name == 'toUpperCase': return wrap(lambda args,this,env: str(this).upper())
    if name == 'toLowerCase': return wrap(lambda args,this,env: str(this).lower())
    if name == 'trim': return wrap(lambda args,this,env: str(this).strip())
    if name == 'trimStart': return wrap(lambda args,this,env: str(this).lstrip())
    if name == 'trimEnd': return wrap(lambda args,this,env: str(this).rstrip())
    if name == 'charAt': return wrap(lambda args,this,env: str(this)[to_int(args[0]) if args else 0:to_int(args[0]) + 1 if args else 1])
    if name == 'charCodeAt':
        def f(args,this,env):
