    if name == 'lastIndexOf': return wrap(lambda args,this,env: str(this).rfind(to_string(args[0]) if args else 'undefined'))
    if name == 'includes': return wrap(lambda args,this,env: (to_string(args[0]) if args else 'undefined') in str(this))
    if name == 'startsWith': return wrap(lambda args,this,env: str(this).startswith(to_string(args[0]) if args else 'undefined'))
    if name == 'endsWith': return wrap(lambda args,this,env: str(this).endswith(to_string(args[0]) if args else 'undefined'))
