    if name == 'padStart': return wrap(lambda args,this,env: str(this).rjust(to_int(args[0]), to_string(args[1])[:1] if len(args)>1 else ' '))
    if name == 'padEnd': return wrap(lambda args,this,env: str(this).ljust(to_int(args[0]), to_string(args[1])[:1] if len(args)>1 else ' '))
