    if name == 'toFixed': return wrap(lambda args,this,env: (f"{to_number(this):.{max(0,to_int(args[0]) if args else 0)}f}"))
    if name in ('valueOf',): return wrap(lambda args,this,env: this)
    return None

def regexp_method(name):
    def wrap(fn): return native(name, fn)
    if name == 'test': return wrap(lambda args,this,env: bool(this._re.search(to_string(args[0]) if args else 'undefined')))
