def py_to_js(x):
    if x is None: return None
    if isinstance(x, bool): return x
    if isinstance(x, (int,float,str)): return x
    if isinstance(x, list): return JSArray([py_to_js(i) for i in x])
    if isinstance(x, dict): return JSObject(OrderedDict((k,py_to_js(v)) for k,v in x.items()))
    return UNDEFINED

def js_to_py_json(v, in_array=False):
    if v is UNDEFINED or isinstance(v, JSFunction):
        return None if in_array else Ellipsis
    if v is None or isinstance(v,(bool,int,str)): return v
    if isinstance(v, float):
        if math.isnan(v) or math.isinf(v): return None
        return v
    if isinstance(v, JSBigInt):
        raise JSThrown(JSErrorObject('TypeError','bigint are forbidden in JSON.stringify'))
    if isinstance(v, JSArray): return [js_to_py_json(x, True) for x in v.items]
    if isinstance(v, JSObject):
        d=OrderedDict()
        for k,val in v.props.items():
            pv=js_to_py_json(val, False)
            if pv is not Ellipsis: d[k]=pv
        return d
    return to_string(v)

def json_stringify(args,this,env):
    v=args[0] if args else UNDEFINED
    pv=js_to_py_json(v, False)
    if pv is Ellipsis: return UNDEFINED
    return json.dumps(pv, ensure_ascii=False, separators=(',',':'))

def json_parse(args,this,env):
    return py_to_js(json.loads(to_string(args[0]) if args else 'undefined'))

def make_error_ctor(name):
    def ctor(args,this,env): return JSErrorObject(name, to_string(args[0]) if args else "")
    return native(name, ctor)

def make_global(std_enabled=False, script_args=None):
    env=Env()
    env.declare('globalThis', UNDEFINED)  # patched below
    env.declare('this', UNDEFINED)
    env.declare('undefined', UNDEFINED)
    env.declare('NaN', float('nan')); env.declare('Infinity', float('inf'))
    def do_print(args,this,env2):
        sys.stdout.write(" ".join(inspect_js(a, True) for a in args) + "\n"); sys.stdout.flush(); return UNDEFINED
    env.declare('print', native('print', do_print))
    console=JSObject({'log': native('log', do_print)})
    env.declare('console', console)
    env.declare('scriptArgs', JSArray(script_args or []))
    env.declare('eval', native('eval', lambda args,this,e: run_source(to_string(args[0]) if args else '', '<eval>', e, module=False, want_result=True)))
    env.declare('parseInt', native('parseInt', lambda args,this,e: parse_int(args)))
    env.declare('parseFloat', native('parseFloat', lambda args,this,e: parse_float(args)))
    env.declare('isNaN', native('isNaN', lambda args,this,e: math.isnan(float(to_number(args[0] if args else UNDEFINED)))))
    env.declare('isFinite', native('isFinite', lambda args,this,e: math.isfinite(float(to_number(args[0] if args else UNDEFINED)))))
    # Constructors and namespaces
    env.declare('Array', make_array_ctor())
    env.declare('Object', make_object_ctor())
    env.declare('String', make_string_ctor())
    env.declare('Number', make_number_ctor())
    env.declare('Boolean', make_boolean_ctor())
    env.declare('BigInt', native('BigInt', lambda args,this,e: JSBigInt(to_int(args[0] if args else 0))))
    for n in ['Error','TypeError','SyntaxError','ReferenceError','RangeError','EvalError','URIError','AggregateError','InternalError']:
        env.declare(n, make_error_ctor(n))
    env.declare('JSON', JSObject({'stringify': native('stringify', json_stringify), 'parse': native('parse', json_parse)}))
    env.declare('Math', make_math())
    env.declare('Date', make_date_ctor())
    env.declare('RegExp', native('RegExp', lambda args,this,e: JSRegExp(to_string(args[0]) if args else '', to_string(args[1]) if len(args)>1 else '')))
    env.declare('performance', JSObject({'now': native('now', lambda args,this,e: time.time()*1000.0)}))
    env.declare('__loadScript', native('__loadScript', lambda args,this,e: run_file(to_string(args[0]), e, module=False)))
    # Placeholder constructor names so typeof/Object.getOwnPropertyNames resembles qjs.
    for n in ['Map','Set','WeakMap','WeakSet','WeakRef','Promise','Proxy','Reflect','Symbol','ArrayBuffer','SharedArrayBuffer','DataView','Atomics','Iterator','FinalizationRegistry','Int8Array','Uint8Array','Uint8ClampedArray','Int16Array','Uint16Array','Int32Array','Uint32Array','BigInt64Array','BigUint64Array','Float16Array','Float32Array','Float64Array','Function']:
        if not env.has(n): env.declare(n, native(n, lambda args,this,e: JSObject(class_name=n)))
    env.set('globalThis', JSObject(env.vars, class_name='global'))
    env.set('this', env.get('globalThis'))
    if std_enabled:
        env.declare('std', make_std(env)); env.declare('os', make_os())
    return env

def parse_int(args):
    s=to_string(args[0] if args else UNDEFINED).lstrip(); radix=to_int(args[1]) if len(args)>1 and args[1] is not UNDEFINED else 0
    try:
        sign=-1 if s.startswith('-') else 1
        if s and s[0] in '+-': s=s[1:]
        if radix==0:
            if s.lower().startswith('0x'): radix=16; s=s[2:]
            else: radix=10
        m=re.match(r'[0-9a-zA-Z]+', s)
        return sign*int(m.group(0), radix) if m else float('nan')
    except Exception: return float('nan')

def parse_float(args):
    s=to_string(args[0] if args else UNDEFINED).lstrip()
    m=re.match(r'[+-]?(Infinity|((\d+\.?\d*)|(\.\d+))([eE][+-]?\d+)?)', s)
    if not m: return float('nan')
    return float(m.group(0))

def make_array_ctor():
    def ctor(args,this,env):
        if len(args)==1 and isinstance(args[0], (int,float)) and not isinstance(args[0], bool): return JSArray([UNDEFINED]*max(0,int(args[0])))
        return JSArray(args)
    f=native('Array', ctor)
    f.props['isArray']=native('isArray', lambda args,this,e: isinstance(args[0] if args else UNDEFINED, JSArray))
    f.props['from']=native('from', lambda args,this,e: JSArray((args[0].items if isinstance(args[0],JSArray) else list(to_string(args[0] if args else '')))))
    return f

def make_object_ctor():
    f=native('Object', lambda args,this,e: args[0] if args and isinstance(args[0],JSObject) else JSObject())
    f.props['keys']=native('keys', lambda args,this,e: JSArray(list((args[0].props.keys() if isinstance(args[0],JSObject) else []))))
    f.props['values']=native('values', lambda args,this,e: JSArray(list((args[0].props.values() if isinstance(args[0],JSObject) else []))))
    f.props['entries']=native('entries', lambda args,this,e: JSArray([JSArray([k,v]) for k,v in (args[0].props.items() if isinstance(args[0],JSObject) else [])]))
    f.props['getOwnPropertyNames']=native('getOwnPropertyNames', lambda args,this,e: own_property_names(args[0] if args else UNDEFINED))
    def assign(args,this,e):
        target=args[0] if args and isinstance(args[0],JSObject) else JSObject()
        for src in args[1:]:
            if isinstance(src,JSObject):
                for k,v in src.props.items(): target.props[k]=v
        return target
    f.props['assign']=native('assign', assign)
    return f

def own_property_names(o):
    if isinstance(o, JSArray): return JSArray([str(i) for i in range(len(o.items))] + list(o.props.keys()) + ['length'])
    if isinstance(o, JSObject): return JSArray(list(o.props.keys()))
    if isinstance(o, str): return JSArray([str(i) for i in range(len(o))] + ['length'])
    return JSArray([])

def make_string_ctor():
    f=native('String', lambda args,this,e: to_string(args[0] if args else ''))
    f.props['fromCharCode']=native('fromCharCode', lambda args,this,e: ''.join(chr(to_int(a)&0xffff) for a in args))
    f.props['fromCodePoint']=native('fromCodePoint', lambda args,this,e: ''.join(chr(to_int(a)) for a in args))
    return f

def make_number_ctor():
    f=native('Number', lambda args,this,e: to_number(args[0] if args else 0))
    f.props['isNaN']=native('isNaN', lambda args,this,e: isinstance(args[0] if args else None,float) and math.isnan(args[0]))
    f.props['isFinite']=native('isFinite', lambda args,this,e: isinstance(args[0] if args else None,(int,float)) and math.isfinite(args[0]))
    f.props['parseInt']=native('parseInt', lambda args,this,e: parse_int(args))
    f.props['parseFloat']=native('parseFloat', lambda args,this,e: parse_float(args))
    return f

def make_boolean_ctor(): return native('Boolean', lambda args,this,e: is_truthy(args[0] if args else False))

def make_math():
    props={'PI':math.pi,'E':math.e,'LN2':math.log(2),'LN10':math.log(10),'LOG2E':1/math.log(2),'LOG10E':1/math.log(10),'SQRT2':math.sqrt(2),'SQRT1_2':math.sqrt(0.5)}
    funcs={
