        'ceil':lambda a: math.ceil(to_number(a[0] if a else UNDEFINED)), 'round':lambda a: math.floor(to_number(a[0])+0.5) if a else float('nan'),
        'trunc':lambda a: math.trunc(to_number(a[0] if a else UNDEFINED)), 'sqrt':lambda a: math.sqrt(to_number(a[0] if a else UNDEFINED)),
        'pow':lambda a: to_number(a[0])**to_number(a[1]), 'max':lambda a: max([to_number(x) for x in a]) if a else float('-inf'),
        'min':lambda a: min([to_number(x) for x in a]) if a else float('inf'), 'random':lambda a: random.random(),
        'sin':lambda a: math.sin(to_number(a[0])), 'cos':lambda a: math.cos(to_number(a[0])), 'tan':lambda a: math.tan(to_number(a[0])),
        'asin':lambda a: math.asin(to_number(a[0])), 'acos':lambda a: math.acos(to_number(a[0])), 'atan':lambda a: math.atan(to_number(a[0])),
        'atan2':lambda a: math.atan2(to_number(a[0]),to_number(a[1])), 'log':lambda a: math.log(to_number(a[0])), 'exp':lambda a: math.exp(to_number(a[0])),
